package cz.ceskymedvidek.app

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

object DomecekSprite {
    val words = listOf(
        "dům","byt","pokoj","postel","polštář",
        "deka","stůl","židle","okno","dveře",
        "lampa","skříň","pohovka","televize","telefon",
        "kniha","hračka","míč","kočka","pes",
        "jíst","pít","spát","sedět","stát"
    )

    private const val DATA = ""

    private val sheet: Bitmap by lazy {
        BitmapFactory.decodeByteArray(Base64.decode(DATA, Base64.DEFAULT), 0, Base64.decode(DATA, Base64.DEFAULT).size)
    }

    fun bitmapFor(word: String): Bitmap? {
        val index = words.indexOf(word)
        if (index < 0) return null
        val cellW = sheet.width / 5
        val cellH = sheet.height / 5
        val x = (index % 5) * cellW
        val y = (index / 5) * cellH
        if (x < 0 || y < 0 || x + cellW > sheet.width || y + cellH > sheet.height) return null
        return Bitmap.createBitmap(sheet, x, y, cellW, cellH)
    }
}
